58	/**
59	 * Crawls the site as a mock admin, following every internal link reachable
60	 * from `/` and `/footy` — including the `src/app/footy/**` admin surface that
61	 * an unauthenticated crawl only ever sees a redirect for.
62	 *
63	 * Writes a JSON report in the same shape as the v1 linkinator CLI
64	 * (`--format json`), so `.github/workflows/link-check.yml` can summarise it
65	 * unchanged.
66	 *
67	 * @param options - See {@link RunLinkCheckOptions}.
68	 * @returns The number of broken internal links found.
69	 */
70	export async function runLinkCheck({
71	    baseUrl,
72	    configPath = 'linkinator.config.json',
73	    reportPath = DEFAULT_REPORT_PATH,
74	}: RunLinkCheckOptions = {}): Promise<number> {
75	    const origin = resolveBaseUrl(baseUrl);
76	    const config = readLinkinatorConfig(configPath);
77	    const checker = new LinkChecker();
78	
79	    checker.on('link', (link) => {
80	        const status = String(link.status ?? '—');
81	        if (link.state === LinkState.BROKEN) {
82	            console.error(
83	                `[${status}] BROKEN ${link.url} (from ${String(link.parent ?? '?')})`,
84	            );
85	        } else {
86	            console.log(`[${status}] ${link.url}`);
87	        }
88	    });
89	
90	    const result = await checker.check({
91	        path: [`${origin}/`, `${origin}/footy`],
92	        recurse: config.recurse ?? true,
93	        linksToSkip: config.skip ?? [],
94	        retry: config.retry ?? true,
95	        concurrency: config.concurrency ?? 20,
96	        timeout: config.timeout ?? 10_000,
97	        headers: { Cookie: ADMIN_COOKIE },
98	    });
99	
100	    writeFileSync(reportPath, JSON.stringify(result, null, 2));
101	
102	    const brokenCount = result.links.filter(
103	        (link) => link.state === LinkState.BROKEN,
104	    ).length;
105	    console.log(
106	        `\n${result.links.length} links checked, ${brokenCount} broken.`,
107	    );
108	    return brokenCount;
109	}
110	
111	/* c8 ignore start -- entrypoint wiring; the crawl itself is exercised by CI */
112	if (process.argv[1] === fileURLToPath(import.meta.url)) {
113	    void (async () => {
114	        try {
115	            const brokenCount = await runLinkCheck();
116	            process.exitCode = brokenCount > 0 ? 1 : 0;
117	        } catch (error) {
118	            console.error(error);
119	            process.exitCode = 1;
120	        }
121	    })();
122	}
123	/* c8 ignore stop */
