250	/**
251	 * Finds the optimal split of players into two balanced teams.
252	 *
253	 * The function evaluates all possible team combinations and selects the one that minimizes
254	 * the differences in team attributes (e.g., skill level, age). When multiple splits have
255	 * equal differences, the lexicographically smallest team mask is preferred for consistency.
256	 *
257	 * @param players - An array of player candidates to be split into teams. Must contain an even
258	 *                  number of at least 2 players.
259	 * @returns A {@link TeamSplit} object containing the two balanced teams (teamA and teamB) and
260	 *          their calculated differences.
261	 * @throws {ValidationError} If the number of players is less than 2 or not an even number.
262	 * @throws {InternalError} If unable to determine balanced teams (should not occur with valid input).
263	 *
264	 * @remarks
265	 * - The function calculates an average age from players with known ages to handle cases where
266	 *   some players may have null age values.
267	 * - Team balance is determined by comparing differences in various attributes using
268	 *   {@link calculateDiffs} and {@link compareDiffs}.
269	 * - The algorithm uses bitmasking via {@link combForeach} to efficiently iterate through
270	 *   all possible team combinations.
271	 */
272	const findBestSplit = (players: PickerCandidate[]): TeamSplit => {
273	    /* v8 ignore next -- upstream selection always passes even-sized arrays >= 2 */
274	    if (players.length < 2 || players.length % 2 !== 0) {
275	        throw new ValidationError(
276	            'Cannot split teams: expected an even number of at least two players.',
277	        );
278	    }
279	
280	    const teamSize = players.length / 2;
281	    const knownAges = players
282	        .map((player) => player.age)
283	        .filter((age): age is number => age !== null);
284	    const averageKnownAge =
285	        knownAges.length > 0 ? sum(knownAges) / knownAges.length : 0;
286	
287	    let bestSplit: TeamSplit | null = null;
288	    let bestSplitMask: bigint | null = null;
289	    combForeach(teamSize, players, (teamA, teamB, _teamAIndexes, teamAMask) => {
290	        const diffs = calculateDiffs(teamA, teamB, averageKnownAge);
291	
292	        if (!bestSplit) {
293	            bestSplit = { teamA, teamB, diffs };
294	            bestSplitMask = teamAMask;
295	            return;
296	        }
297	
298	        const diffComparison = compareDiffs(diffs, bestSplit.diffs);
299	        if (
300	            diffComparison < 0 ||
301	            (diffComparison === 0 &&
302	                bestSplitMask !== null &&
303	                teamAMask < bestSplitMask)
304	        ) {
305	            bestSplit = { teamA, teamB, diffs };
306	            bestSplitMask = teamAMask;
307	        }
308	    });
309	
310	    /* v8 ignore next -- combForeach always emits at least one split for valid input */
311	    if (!bestSplit) {
312	        throw new InternalError('Unable to determine balanced teams.');
313	    }
314	
315	    return bestSplit;
316	};
